package cli

import (
	"fmt"
	"io"
	"os"
	"path/filepath"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func addCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "add <feature>",
		Short: "Create a feature workspace",
		Args:  cobra.ExactArgs(1),
		Run: func(cmd *cobra.Command, args []string) {
			feature := args[0]
			root := internal.FeaturePath(feature)

			wsRoot := internal.TwsRoot()
			internal.Must(os.MkdirAll(filepath.Join(wsRoot, ".tws-workspace"), 0755))
			internal.Must(os.MkdirAll(filepath.Join(root, "worktrees"), 0755))
			internal.Must(os.WriteFile(filepath.Join(root, "FEATURE.md"), []byte("# "+feature+"\n"), 0644))

			// Create inject/ dir
			injectDir := internal.InjectPath(root)
			internal.Must(os.MkdirAll(injectDir, 0755))

			// Copy template into inject/ if available
			templateDir := internal.TemplatePath()
			if templateDir != "" {
				count, err := copyDir(templateDir, injectDir)
				if err != nil {
					fmt.Printf("Warning: template copy failed: %v\n", err)
				} else if count > 0 {
					fmt.Printf("Copied %d file(s) from template\n", count)
				}
			}

			// Add default CLAUDE.local.md if not provided by template
			claudeLocal := filepath.Join(injectDir, "CLAUDE.local.md")
			if _, err := os.Stat(claudeLocal); os.IsNotExist(err) {
				internal.Must(os.WriteFile(claudeLocal, []byte("# "+feature+" - shared context\n\nThis file is symlinked into every worktree for this feature.\nEdit it in the workspace inject/ directory.\n"), 0644))
			}

			fmt.Println("Feature added:", feature)
		},
	}
}

// copyDir copies all files from src to dst, preserving directory structure.
// Does not overwrite existing files. Returns the count of files copied.
func copyDir(src, dst string) (int, error) {
	count := 0
	err := filepath.Walk(src, func(srcPath string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}

		relPath, err := filepath.Rel(src, srcPath)
		if err != nil {
			return err
		}
		if relPath == "." {
			return nil
		}

		dstPath := filepath.Join(dst, relPath)

		if info.IsDir() {
			return os.MkdirAll(dstPath, 0755)
		}

		// Skip if exists
		if _, err := os.Stat(dstPath); err == nil {
			return nil
		}

		// Copy file
		in, err := os.Open(srcPath)
		if err != nil {
			return err
		}
		defer in.Close() //nolint:errcheck

		out, err := os.Create(dstPath)
		if err != nil {
			return err
		}
		defer out.Close() //nolint:errcheck

		if _, err := io.Copy(out, in); err != nil {
			return err
		}
		count++
		return nil
	})
	return count, err
}

package cli

import (
	"fmt"
	"os"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func renameCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "rename",
		Short: "Rename a feature or branch",
	}

	cmd.AddCommand(renameFeatureCmd())
	cmd.AddCommand(renameBranchCmd())

	return cmd
}

func renameFeatureCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "feature <old-name> <new-name>",
		Short: "Rename a feature",
		Args:  cobra.ExactArgs(2),
		Run: func(cmd *cobra.Command, args []string) {
			oldName := args[0]
			newName := args[1]

			oldPath := internal.FeaturePath(oldName)
			newPath := internal.FeaturePath(newName)

			if _, err := os.Stat(oldPath); os.IsNotExist(err) {
				fmt.Printf("Feature not found: %s\n", oldName)
				os.Exit(1)
			}

			if _, err := os.Stat(newPath); err == nil {
				fmt.Printf("Feature already exists: %s\n", newName)
				os.Exit(1)
			}

			if err := os.Rename(oldPath, newPath); err != nil {
				fmt.Printf("Error renaming: %v\n", err)
				os.Exit(1)
			}

			fmt.Printf("Renamed feature: %s → %s\n", oldName, newName)
		},
	}
}

func renameBranchCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "branch <feature> <old-name> <new-name>",
		Short: "Rename a branch within a feature",
		Args:  cobra.ExactArgs(3),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			switch len(args) {
			case 0:
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			case 1:
				return internal.ListBranches(args[0]), cobra.ShellCompDirectiveNoFileComp
			default:
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
		},
		Run: func(cmd *cobra.Command, args []string) {
			internal.RequireTool("git")

			feature := args[0]
			oldName := args[1]
			newName := args[2]

			featurePath := internal.FeaturePath(feature)

			// Update stack.yaml
			stack, err := internal.LoadStack(featurePath)
			if err != nil {
				fmt.Printf("No stack.yaml found for feature: %s\n", feature)
				os.Exit(1)
			}

			if !internal.RenameBranch(&stack, oldName, newName) {
				fmt.Printf("Branch %q not found in stack\n", oldName)
				os.Exit(1)
			}

			internal.Must(internal.SaveStack(featurePath, stack))

			// Rename worktree directory if active
			oldPath := internal.WorktreePath(feature, oldName)
			newPath := internal.WorktreePath(feature, newName)

			if _, err := os.Stat(oldPath); err == nil {
				// Remove worktree, rename git branch, re-add
				internal.Must(internal.Run("git", "worktree", "remove", "--force", oldPath))
				internal.Must(internal.Run("git", "branch", "-m", oldName, newName))
				internal.Must(internal.Run("git", "worktree", "add", newPath, newName))
			} else {
				// Archived — just rename the git branch
				internal.Must(internal.Run("git", "branch", "-m", oldName, newName))
			}

			// Kill stale tmux session
			oldSession := sanitizeSessionName(feature + "/" + oldName)
			if sessionExists(oldSession) {
				_ = internal.RunSilent("tmux", "kill-session", "-t", oldSession)
			}

			// Update decisions.yaml branch references
			decisions, err := internal.LoadDecisions(featurePath)
			if err == nil {
				for i := range decisions.Entries {
					if decisions.Entries[i].Branch == oldName {
						decisions.Entries[i].Branch = newName
					}
				}
				_ = internal.SaveDecisions(featurePath, decisions)
			}

			fmt.Printf("Renamed branch: %s → %s (in feature %s)\n", oldName, newName, feature)
		},
	}
}

package internal

import (
	"os"
	"path/filepath"

	"gopkg.in/yaml.v3"
)

type Config struct {
	Workspaces   map[string]string `yaml:"workspaces"`
	AgentCommand string            `yaml:"agent_command"`
	UseTmux      *bool             `yaml:"use_tmux"`
}

func (c Config) GetAgentCommand() string {
	if c.AgentCommand != "" {
		return c.AgentCommand
	}
	return "claude"
}

// ConfigPath returns the global config path.
func ConfigPath() string {
	home, _ := os.UserHomeDir()
	return filepath.Join(home, ".config", "tws", "config.yaml")
}

func repoConfigPath() string {
	root, err := RepoRoot()
	if err != nil {
		return ""
	}
	return filepath.Join(root, ".tws", "config.yaml")
}

func loadConfigFile(path string) Config {
	if path == "" {
		return Config{}
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return Config{}
	}
	var cfg Config
	if err := yaml.Unmarshal(data, &cfg); err != nil {
		return Config{}
	}
	return cfg
}

// LoadConfig loads the global config, then merges per-repo config on top.
// Per-repo values override global values when set.
func LoadConfig() Config {
	cfg := loadConfigFile(ConfigPath())
	repo := loadConfigFile(repoConfigPath())

	if repo.AgentCommand != "" {
		cfg.AgentCommand = repo.AgentCommand
	}
	if repo.UseTmux != nil {
		cfg.UseTmux = repo.UseTmux
	}
	if len(repo.Workspaces) > 0 {
		if cfg.Workspaces == nil {
			cfg.Workspaces = make(map[string]string)
		}
		for k, v := range repo.Workspaces {
			cfg.Workspaces[k] = v
		}
	}

	return cfg
}

// SaveConfigFile writes a config to the given path.
func SaveConfigFile(path string, cfg Config) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return err
	}
	data, err := yaml.Marshal(&cfg)
	if err != nil {
		return err
	}
	return os.WriteFile(path, data, 0644)
}

// RepoConfigPath exports the per-repo config path for the config command.
func RepoConfigPath() string {
	return repoConfigPath()
}

// LoadConfigFile loads a single config file (exported for the config command).
func LoadConfigFile(path string) Config {
	return loadConfigFile(path)
}

// TemplatePath returns the template directory path.
// Per-repo (.tws/templates/) takes priority over global (~/.config/tws/templates/).
// Returns empty string if neither exists.
func TemplatePath() string {
	// Per-repo first
	repoPath := repoConfigPath()
	if repoPath != "" {
		repoTemplates := filepath.Join(filepath.Dir(repoPath), "templates")
		if info, err := os.Stat(repoTemplates); err == nil && info.IsDir() {
			return repoTemplates
		}
	}

	// Global
	home, _ := os.UserHomeDir()
	globalTemplates := filepath.Join(home, ".config", "tws", "templates")
	if info, err := os.Stat(globalTemplates); err == nil && info.IsDir() {
		return globalTemplates
	}

	return ""
}

package internal

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"gopkg.in/yaml.v3"
)

type StackEntry struct {
	Name string `yaml:"name"`
	Base string `yaml:"base"`
}

type Stack struct {
	Branches []StackEntry `yaml:"branches"`
}

// HasBranch checks if a branch name already exists in the stack.
func HasBranch(s Stack, name string) bool {
	for _, e := range s.Branches {
		if e.Name == name {
			return true
		}
	}
	return false
}

// RenameBranch renames a branch in the stack, updating both Name and Base references.
func RenameBranch(s *Stack, oldName, newName string) bool {
	found := false
	for i := range s.Branches {
		if s.Branches[i].Name == oldName {
			s.Branches[i].Name = newName
			found = true
		}
		if s.Branches[i].Base == oldName {
			s.Branches[i].Base = newName
		}
	}
	return found
}

func StackPath(featurePath string) string {
	return filepath.Join(featurePath, "stack.yaml")
}

func LoadStack(featurePath string) (Stack, error) {
	data, err := os.ReadFile(StackPath(featurePath))
	if err != nil {
		return Stack{}, err
	}
	var s Stack
	if err := yaml.Unmarshal(data, &s); err != nil {
		return Stack{}, err
	}
	return s, nil
}

func SaveStack(featurePath string, s Stack) error {
	data, err := yaml.Marshal(&s)
	if err != nil {
		return err
	}
	return os.WriteFile(StackPath(featurePath), data, 0644)
}

// TopoSort returns branches in dependency order (parents before children).
// Returns an error if the graph contains a cycle.
func TopoSort(s Stack) ([]StackEntry, error) {
	// Build adjacency: base → children
	entryMap := make(map[string]StackEntry)
	children := make(map[string][]string)
	inDegree := make(map[string]int)

	for _, e := range s.Branches {
		entryMap[e.Name] = e
		inDegree[e.Name] = 0
	}

	for _, e := range s.Branches {
		// Only count edges where the base is also a tracked branch
		if _, ok := entryMap[e.Base]; ok {
			children[e.Base] = append(children[e.Base], e.Name)
			inDegree[e.Name]++
		}
	}

	// Kahn's algorithm
	var queue []string
	for name, deg := range inDegree {
		if deg == 0 {
			queue = append(queue, name)
		}
	}

	var sorted []StackEntry
	for len(queue) > 0 {
		name := queue[0]
		queue = queue[1:]
		sorted = append(sorted, entryMap[name])
		for _, child := range children[name] {
			inDegree[child]--
			if inDegree[child] == 0 {
				queue = append(queue, child)
			}
		}
	}

	if len(sorted) != len(s.Branches) {
		return nil, fmt.Errorf("cycle detected in stack.yaml")
	}
	return sorted, nil
}

// Descendants returns all transitive children of the given branch.
func Descendants(s Stack, branch string) map[string]bool {
	children := make(map[string][]string)
	for _, e := range s.Branches {
		children[e.Base] = append(children[e.Base], e.Name)
	}

	result := make(map[string]bool)
	queue := []string{branch}
	for len(queue) > 0 {
		name := queue[0]
		queue = queue[1:]
		for _, child := range children[name] {
			if !result[child] {
				result[child] = true
				queue = append(queue, child)
			}
		}
	}
	return result
}

// PrintTree prints the stack as an indented dependency tree.
func PrintTree(s Stack) {
	children := make(map[string][]string)
	roots := make(map[string]bool)

	for _, e := range s.Branches {
		roots[e.Name] = true
	}
	for _, e := range s.Branches {
		children[e.Base] = append(children[e.Base], e.Name)
		// If base is a tracked branch, this entry is not a root
		for _, other := range s.Branches {
			if other.Name == e.Base {
				delete(roots, e.Name)
				break
			}
		}
	}

	var printNode func(name, prefix string, isLast bool)
	printNode = func(name, prefix string, isLast bool) {
		connector := "├── "
		if isLast {
			connector = "└── "
		}
		fmt.Println(prefix + connector + name)

		childPrefix := prefix
		if isLast {
			childPrefix += "    "
		} else {
			childPrefix += "│   "
		}

		kids := children[name]
		for i, child := range kids {
			printNode(child, childPrefix, i == len(kids)-1)
		}
	}

	// Print from each root's base (usually "main")
	bases := make(map[string]bool)
	for _, e := range s.Branches {
		if roots[e.Name] {
			bases[e.Base] = true
		}
	}

	for base := range bases {
		fmt.Printf("(%s)\n", base)
		kids := children[base]
		for i, child := range kids {
			printNode(child, "", i == len(kids)-1)
		}
	}

	if len(s.Branches) == 0 {
		fmt.Println("No branches tracked. Use 'ts new <feature> <branch>' to add branches.")
	}
}

// FormatBranchStatus formats a branch sync result for display.
func FormatBranchStatus(name, status string) string {
	symbols := map[string]string{
		"synced":  "+",
		"failed":  "x",
		"skipped": "-",
	}
	sym := symbols[status]
	if sym == "" {
		sym = "?"
	}
	return fmt.Sprintf("  [%s] %s", sym, name)
}

// DescendantsList returns Descendants as a sorted display string.
func DescendantsList(s Stack, branch string) string {
	descs := Descendants(s, branch)
	var names []string
	for name := range descs {
		names = append(names, name)
	}
	return strings.Join(names, ", ")
}
